func Stop(ctx context.Context, auth *process.AuthorizedInfo, chatID string, force bool) error {
	dc, exists := GetDaemon(chatID)
	if !exists {
		return fmt.Errorf("task %s is not running", chatID)
	}
	if force {
		dc.ForceCancel()
	} else {
		dc.Cancel()
	}
	return nil
}
