      "path": "agent/sandbox/v2/lifecycle.go",
      "content": "package sandboxv2\n\nimport (\n\t\"context\"\n\t\"crypto/rand\"\n\t\"encoding/hex\"\n\t\"fmt\"\n\t\"strings\"\n\n\t\"github.com/yaoapp/kun/log\"\n\t\"github.com/yaoapp/yao/agent/computer\"\n\tagentContext \"github.com/yaoapp/yao/agent/context\"\n\t\"github.com/yaoapp/yao/agent/sandbox/v2/resolve\"\n\t\"github.com/yaoapp/yao/agent/sandbox/v2/types\"\n\tinfra \"github.com/yaoapp/yao/sandbox/v2\"\n\t\"github.com/yaoapp/yao/workspace\"\n)\n\n// BuildIdentifier determines the Computer identifier based on lifecycle policy.\n// Returns \"\" for oneshot (always new). This is a backward-compatible wrapper\n// around resolve.BuildIdentifier, keeping the old signature for existing callers.\nfunc BuildIdentifier(cfg *types.SandboxConfig, ownerID, chatID, assistantID, workspaceID string, metadata map[string]any) string {\n\treturn resolve.BuildIdentifier(cfg.Lifecycle, ownerID, chatID, assistantID, workspaceID)\n}\n\n// ResolveRunner determines which runner to use.\n// Priority: userPref > sandbox.yao runner.name > globalRunner > fallback \"yaocode\".\n// The special value \"use::default\" is treated as \"not set\" at each level,\n// allowing the next level in the chain to take effect.\nfunc ResolveRunner(userPref string, runnerCfg *types.RunnerConfig, globalRunner string) (string, error) {\n\tvar runner string\n\n\t// 1. User explicit preference (skip \"use::default\")\n\tif userPref != \"\" && userPref != \"use::default\" {\n\t\trunner = userPref\n\t}\n\n\t// 2. sandbox.yao runner.name (skip \"use::default\")\n\tif runner == \"\" && runnerCfg != nil && runnerCfg.Name != \"\" && runnerCfg.Name != \"use::default\" {\n\t\trunner = runnerCfg.Name\n\t}\n\n\t// 3. agent.yml global runner (skip \"use::default\")\n\tif runner == \"\" && globalRunner != \"\" && globalRunner != \"use::default\" {\n\t\trunner = globalRunner\n\t}\n\n\t// 4. Fallback\n\tif runner == \"\" {\n\t\trunner = \"yaocode\"\n\t}\n\n\t// Backward-compat alias mapping\n\trunner = canonicalRunner(runner)\n\n\tif !containsRunner(SupportedRunners, runner) {\n\t\treturn \"\", fmt.Errorf(\"unknown runner %q (supported: %v)\", runner, SupportedRunners)\n\t}\n\n\t// Validate against sandbox.yao supports list\n\tif runnerCfg != nil && len(runnerCfg.Supports) > 0 {\n\t\tif !containsRunner(runnerCfg.Supports, runner) {\n\t\t\treturn \"\", fmt.Errorf(\"runner %q not supported by this assistant (supports: %v)\", runner, runnerCfg.Supports)\n\t\t}\n\t}\n\n\treturn runner, nil\n}\n\n// GetComputer obtains or creates a Computer for the current request using the\n// pre-computed SelectionResult from SelectNode. Resource preparation (workspace,\n// box creation) is pipeline-specific; the actual Computer reference is obtained\n// via the unified computer.Lookup path.\n// Returns the Computer, the resolved identifier, and any error.\nfunc GetComputer(ctx *agentContext.Context, cfg *types.SandboxConfig, manager *infra.Manager, sel *SelectionResult) (infra.Computer, string, error) {\n\townerID := resolveOwnerID(ctx)\n\n\tworkspaceID := \"\"\n\tif ctx.Metadata != nil {\n\t\tif ws, ok := ctx.Metadata[\"workspace_id\"].(string); ok && ws != \"\" {\n\t\t\tworkspaceID = ws\n\t\t}\n\t}\n\n\tidentifier := BuildIdentifier(cfg, ownerID, ctx.ChatID, ctx.AssistantID, workspaceID, ctx.Metadata)\n\n\tcfg.Owner = ownerID\n\tcfg.ID = identifier\n\tcfg.WorkspaceID = workspaceID\n\tcfg.ChatID = ctx.ChatID\n\tcfg.NodeID = sel.NodeID\n\n\t// Store assistant ID as a label for reliable lookup by webproxy/settings\n\tif cfg.Labels == nil {\n\t\tcfg.Labels = make(map[string]string)\n\t}\n\tif ctx.AssistantID != \"\" {\n\t\tcfg.Labels[\"sandbox-assistant\"] = ctx.AssistantID\n\t}\n\n\t// Inject user identity into sandbox environment for ownership tracking\n\tif ctx.Authorized != nil {\n\t\tif cfg.Environment == nil {\n\t\t\tcfg.Environment = make(map[string]string)\n\t\t}\n\t\tif ctx.Authorized.UserID != \"\" {\n\t\t\tcfg.Environment[\"YAO_USER_ID\"] = ctx.Authorized.UserID\n\t\t}\n\t\tif ctx.Authorized.TeamID != \"\" {\n\t\t\tcfg.Environment[\"YAO_TEAM_ID\"] = ctx.Authorized.TeamID\n\t\t}\n\t}\n\n\tlog.Trace(\"[sandbox/v2] GetComputer: nodeID=%q runner=%q mode=%q workspaceID=%q ownerID=%q image=%q\",\n\t\tsel.NodeID, sel.Runner, sel.Mode, workspaceID, ownerID, cfg.Computer.Image)\n\n\t// --- Pipeline-specific: resource preparation ---\n\tswitch sel.Mode {\n\tcase \"host\":\n\t\tcfg.Kind = \"host\"\n\t\tworkspaceID, identifier = ensureHostWorkspace(cfg, ownerID, workspaceID, identifier)\n\n\tcase \"box\":\n\t\tcfg.Kind = \"box\"\n\t\tif _, newIdent, err := resolveBox(cfg, manager, ownerID, identifier, workspaceID); err != nil {\n\t\t\treturn nil, identifier, err\n\t\t} else {\n\t\t\tidentifier = newIdent\n\t\t}\n\n\tdefault:\n\t\treturn nil, identifier, fmt.Errorf(\"unsupported mode %q for node %q\", sel.Mode, sel.NodeID)\n\t}\n\n\t// --- Unified path: obtain Computer via computer.Lookup ---\n\tcomp, err := computer.Lookup(ctx, &computer.LookupOpts{\n\t\tAuth:          ctx.Authorized,\n\t\tAssistantID:   ctx.AssistantID,\n\t\tWorkspaceID:   cfg.WorkspaceID,\n\t\tChatID:        ctx.ChatID,\n\t\tImage:         cfg.Computer.Image,\n\t\tLifecycle:     cfg.Lifecycle,\n\t\tNodeID:        sel.NodeID,\n\t\tBoxIdentifier: cfg.ID,\n\t})\n\treturn comp, identifier, err\n}\n\n// ensureHostWorkspace generates a default workspace ID when none is provided\n// and ensures the workspace directory + metadata exist on disk (idempotent).\n// Mirrors the default-workspace logic in resolveBox for parity.\nfunc ensureHostWorkspace(cfg *types.SandboxConfig, ownerID, workspaceID, identifier string) (string, string) {\n\tif workspaceID == \"\" && cfg.NodeID != \"\" {\n\t\tworkspaceID = workspace.DefaultWorkspaceID(ownerID, cfg.NodeID)\n\t\tcfg.WorkspaceID = workspaceID\n\t\tif dot := strings.LastIndex(identifier, \".\"); dot >= 0 {\n\t\t\tidentifier = identifier[:dot+1] + workspaceID\n\t\t\tcfg.ID = identifier\n\t\t}\n\t}\n\n\tif workspaceID != \"\" {\n\t\twsm := workspace.M()\n\t\tif _, err := wsm.Get(context.Background(), workspaceID); err != nil {\n\t\t\tif _, createErr := wsm.Create(context.Background(), workspace.CreateOptions{\n\t\t\t\tID:    workspaceID,\n\t\t\t\tOwner: ownerID,\n\t\t\t\tNode:  cfg.NodeID,\n\t\t\t\tName:  \"Default\",\n\t\t\t}); createErr != nil {\n\t\t\t\tlog.Trace(\"[sandbox/v2] auto-create workspace %s failed: %v\", workspaceID, createErr)\n\t\t\t}\n\t\t}\n\t}\n\n\treturn workspaceID, identifier\n}\n\n// resolveBox reuses or creates a box container.\nfunc resolveBox(\n\tcfg *types.SandboxConfig, manager *infra.Manager,\n\townerID, identifier, workspaceID string,\n) (infra.Computer, string, error) {\n\n\tif workspaceID == \"\" && cfg.NodeID != \"\" {\n\t\tworkspaceID = workspace.DefaultWorkspaceID(ownerID, cfg.NodeID)\n\t\tcfg.WorkspaceID = workspaceID\n\t\tif dot := strings.LastIndex(identifier, \".\"); dot >= 0 {\n\t\t\tidentifier = identifier[:dot+1] + workspaceID\n\t\t\tcfg.ID = identifier\n\t\t}\n\t}\n\n\t// Reuse: non-empty identifier → try Get first.\n\tif identifier != \"\" {\n\t\tbox, err := manager.Get(context.Background(), identifier)\n\t\tif err == nil && box != nil {\n\t\t\tif box.IsStopped() {\n\t\t\t\tif startErr := manager.StartBox(context.Background(), identifier); startErr != nil {\n\t\t\t\t\tlog.Trace(\"[sandbox/v2] auto-start stopped box %s failed: %v, creating new\", identifier, startErr)\n\t\t\t\t} else {\n\t\t\t\t\tbox.BindWorkplace(workspaceID)\n\t\t\t\t\treturn box, identifier, nil\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tbox.BindWorkplace(workspaceID)\n\t\t\t\treturn box, identifier, nil\n\t\t\t}\n\t\t}\n\t}\n\n\t// Create new box.\n\tcreateOpts, err := BuildCreateOptions(cfg, identifier, ownerID, workspaceID)\n\tif err != nil {\n\t\treturn nil, identifier, fmt.Errorf(\"build create options: %w\", err)\n\t}\n\tlog.Trace(\"[sandbox/v2] resolveBox: createOpts NodeID=%q Image=%q WorkspaceID=%q ID=%q Owner=%q\", createOpts.NodeID, createOpts.Image, createOpts.WorkspaceID, createOpts.ID, createOpts.Owner)\n\n\t// Oneshot with empty identifier: generate a random one.\n\tif createOpts.ID == \"\" {\n\t\tcreateOpts.ID = randomID()\n\t\tidentifier = createOpts.ID\n\t\tcfg.ID = identifier\n\t}\n\n\tbox, err := manager.Create(context.Background(), createOpts)\n\tif err != nil {\n\t\treturn nil, identifier, fmt.Errorf(\"create computer: %w\", err)\n\t}\n\treturn box, identifier, nil\n}\n\n// LifecycleAction performs the post-request lifecycle operation based on policy.\n// Called in defer after executeSandboxStream completes.\n//\n// NOTE: cfg.ID must NOT be used here — it is a shared mutable field on the\n// Assistant struct and is overwritten by concurrent requests. The authoritative\n// box ID is computer.ComputerInfo().BoxID, which is set once when the Box is\n// created and never changes.\nfunc LifecycleAction(ctx context.Context, cfg *types.SandboxConfig, computer infra.Computer, manager *infra.Manager) {\n\tif computer == nil || cfg == nil {\n\t\treturn\n\t}\n\n\tinfo := computer.ComputerInfo()\n\tboxID := info.BoxID // use the box's own immutable ID, not cfg.ID\n\n\tswitch cfg.Lifecycle {\n\tcase \"oneshot\":\n\t\tif info.Kind == \"box\" && manager != nil {\n\t\t\tif err := manager.Remove(ctx, boxID); err != nil {\n\t\t\t\tlog.Trace(\"[sandbox/v2] oneshot remove %s: %v\", boxID, err)\n\t\t\t}\n\t\t}\n\n\tcase \"session\", \"longrunning\":\n\t\tif info.Kind == \"box\" && manager != nil {\n\t\t\tmanager.Heartbeat(boxID, false, 0) // active=false: request finished, start idle timer\n\t\t}\n\n\tcase \"persistent\":\n\t\t// No action — persistent boxes survive indefinitely.\n\t}\n}\n\n// resolveOwnerID returns teamID if available, otherwise userID.\nfunc resolveOwnerID(ctx *agentContext.Context) string {\n\tif ctx.Authorized != nil {\n\t\tif ctx.Authorized.TeamID != \"\" {\n\t\t\treturn ctx.Authorized.TeamID\n\t\t}\n\t\tif ctx.Authorized.UserID != \"\" {\n\t\t\treturn ctx.Authorized.UserID\n\t\t}\n\t}\n\treturn \"anonymous\"\n}\n\nfunc randomID() string {\n\tb := make([]byte, 8)\n\t_, _ = rand.Read(b)\n\treturn hex.EncodeToString(b)\n}\n"
    },
    {
      "path": "agent/computer/lookup.go",
      "content": "package computer\n\nimport (\n\t\"context\"\n\t\"errors\"\n\t\"fmt\"\n\n\t\"github.com/yaoapp/yao/agent/sandbox/v2/resolve\"\n\toauthtypes \"github.com/yaoapp/yao/openapi/oauth/types\"\n\tsandbox \"github.com/yaoapp/yao/sandbox/v2\"\n\t\"github.com/yaoapp/yao/tai/registry\"\n\ttaiTypes \"github.com/yaoapp/yao/tai/types\"\n\t\"github.com/yaoapp/yao/workspace\"\n)\n\n// LookupOpts carries the parameters for Lookup.\n//\n// Image and Lifecycle should always be provided by callers (fetched from\n// assistant config). This keeps the computer package free of assistant-package\n// imports, avoiding an import cycle.\ntype LookupOpts struct {\n\tAuth        *oauthtypes.AuthorizedInfo\n\tAssistantID string\n\tWorkspaceID string\n\tChatID      string\n\tImage       string // container image (determines box vs host mode)\n\tLifecycle   string // \"oneshot\" | \"session\" | \"longrunning\" | \"persistent\"\n\n\t// --- Optional overrides ---\n\tNodeID        string // skip workspace→node lookup when pre-resolved\n\tBoxIdentifier string // skip BuildIdentifier recomputation (oneshot needs this)\n}\n\n// Lookup is the single entry point for resolving parameters into a Computer\n// (Box or Host). Both the agent pipeline (GetComputer) and API handlers\n// (resolveComputer) use this function.\n//\n// Return semantics (consistent with the original resolveComputer):\n//   - (nil, nil)  — box mode, sandbox not running (not found / stopped / oneshot unresolvable)\n//   - (comp, nil) — computer found\n//   - (nil, err)  — real error (assistant missing, workspace invalid, node offline, etc.)\nfunc Lookup(ctx context.Context, opts *LookupOpts) (sandbox.Computer, error) {\n\timage, lifecycle := opts.Image, opts.Lifecycle\n\tnodeID := opts.NodeID\n\n\t// 1. Workspace is required.\n\tif opts.WorkspaceID == \"\" {\n\t\treturn nil, errors.New(\"computer.Lookup: workspace ID is empty\")\n\t}\n\n\t// 2. Resolve node from workspace when not overridden.\n\tif nodeID == \"\" {\n\t\tvar err error\n\t\tnodeID, err = workspace.M().NodeForWorkspace(ctx, opts.WorkspaceID)\n\t\tif err != nil {\n\t\t\treturn nil, fmt.Errorf(\"computer.Lookup: cannot resolve node for workspace %q: %w\", opts.WorkspaceID, err)\n\t\t}\n\t\tif nodeID == \"\" {\n\t\t\treturn nil, fmt.Errorf(\"computer.Lookup: workspace %q has no bound node\", opts.WorkspaceID)\n\t\t}\n\t}\n\n\t// 3. Registry → NodeCandidate → ResolveMode\n\tmeta, ok := registry.Global().Get(nodeID)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"computer.Lookup: node %q offline or removed\", nodeID)\n\t}\n\tcandidate := toNodeCandidate(meta)\n\tmode := resolve.ResolveMode(&candidate, \"\", image)\n\n\t// 4. ownerID (TeamID > UserID > \"anonymous\")\n\townerID := deriveOwnerID(opts.Auth)\n\n\t// 5. Dispatch by mode + BindWorkplace\n\tmgr := sandbox.M()\n\tswitch mode {\n\tcase \"host\":\n\t\thost, err := mgr.Host(ctx, nodeID)\n\t\tif err != nil {\n\t\t\treturn nil, fmt.Errorf(\"computer.Lookup: host %q: %w\", nodeID, err)\n\t\t}\n\t\thost.BindWorkplace(opts.WorkspaceID)\n\t\treturn host, nil\n\n\tcase \"box\":\n\t\tidentifier := opts.BoxIdentifier\n\t\tif identifier == \"\" {\n\t\t\tidentifier = resolve.BuildIdentifier(lifecycle, ownerID, opts.ChatID, opts.AssistantID, opts.WorkspaceID)\n\t\t}\n\t\tif identifier == \"\" {\n\t\t\treturn nil, nil // oneshot without override: cannot look up\n\t\t}\n\t\tbox, err := mgr.Get(ctx, identifier)\n\t\tif err != nil {\n\t\t\tif errors.Is(err, sandbox.ErrNotFound) {\n\t\t\t\treturn nil, nil\n\t\t\t}\n\t\t\treturn nil, fmt.Errorf(\"computer.Lookup: box %q: %w\", identifier, err)\n\t\t}\n\t\tif box.IsStopped() {\n\t\t\treturn nil, nil\n\t\t}\n\t\tbox.BindWorkplace(opts.WorkspaceID)\n\t\treturn box, nil\n\n\tdefault:\n\t\treturn nil, fmt.Errorf(\"computer.Lookup: no feasible mode for node %q (canBox=%v canHost=%v image=%q)\",\n\t\t\tnodeID, candidate.CanBox, candidate.CanHost, image)\n\t}\n}\n\n// toNodeCandidate converts registry NodeMeta to resolve.NodeCandidate.\nfunc toNodeCandidate(n *taiTypes.NodeMeta) resolve.NodeCandidate {\n\treturn resolve.NodeCandidate{\n\t\tID:      n.TaiID,\n\t\tIsLocal: n.TaiID == \"local\" && n.Mode == \"local\",\n\t\tRunners: n.Capabilities.Runners,\n\t\tCanBox:  n.Capabilities.Docker || n.Capabilities.K8s,\n\t\tCanHost: n.Capabilities.HostExec,\n\t\tOS:      n.System.OS,\n\t\tArch:    n.System.Arch,\n\t}\n}\n\n// deriveOwnerID mirrors resolveOwnerID from lifecycle.go.\nfunc deriveOwnerID(auth *oauthtypes.AuthorizedInfo) string {\n\tif auth != nil {\n\t\tif auth.TeamID != \"\" {\n\t\t\treturn auth.TeamID\n\t\t}\n\t\tif auth.UserID != \"\" {\n\t\t\treturn auth.UserID\n\t\t}\n\t}\n\treturn \"anonymous\"\n}\n"
    },
