      "path": "agent/sandbox/v2/dsh/parse.go",
      "content": "package dsh\n\nimport (\n\t\"bufio\"\n\t\"context\"\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"io\"\n\t\"regexp\"\n\t\"strings\"\n\t\"time\"\n\n\tgouJSON \"github.com/yaoapp/gou/json\"\n\t\"github.com/yaoapp/kun/log\"\n\t\"github.com/yaoapp/yao/agent/i18n\"\n\t\"github.com/yaoapp/yao/agent/output/message\"\n\t\"github.com/yaoapp/yao/agent/sandbox/v2/shared\"\n)\n\n// streamParser parses DSH JSON-RPC NDJSON stdout into StreamFunc chunks.\n//\n// Tool lifecycle has two phases:\n//\n//\tPhase 1 (LLM streaming): block-start(tool-call) → tool-call-delta → block-end\n//\tPhase 2 (execution):     tool/call → tool/result\n//\n// The same message_id is reused across phases for UI grouping.\ntype streamParser struct {\n\thandler           message.StreamFunc\n\tpromptedSessionID string\n\tlocale            string\n\tcompleted         bool\n\n\ttextActive    bool\n\tthinkActive   bool\n\ttoolIndex     int\n\tactiveToolID  string\n\ttoolNames     map[string]string\n\ttoolMsgIDs    map[string]string\n\ttoolInputs    map[string]string\n\ttoolSummaries map[string]string\n\ttoolFinished  map[string]bool\n\n\tprepareLoadingMsgID string\n\tcontentStarted      bool\n\tactiveLoadingID     string\n\tloadingSeq          int\n}\n\nfunc newStreamParser(handler message.StreamFunc, promptedSessionID string, locale string, prepareLoadingMsgID string) *streamParser {\n\treturn &streamParser{\n\t\thandler:             handler,\n\t\tpromptedSessionID:   promptedSessionID,\n\t\tlocale:              locale,\n\t\tprepareLoadingMsgID: prepareLoadingMsgID,\n\t\ttoolNames:           make(map[string]string),\n\t\ttoolMsgIDs:          make(map[string]string),\n\t\ttoolInputs:          make(map[string]string),\n\t\ttoolSummaries:       make(map[string]string),\n\t\ttoolFinished:        make(map[string]bool),\n\t}\n}\n\nfunc (p *streamParser) parse(ctx context.Context, stdout io.ReadCloser) error {\n\tdefer p.closeActiveLoading()\n\tdoneParsing := make(chan struct{})\n\tdefer close(doneParsing)\n\tgo func() {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tstdout.Close()\n\t\tcase <-doneParsing:\n\t\t}\n\t}()\n\n\treader := bufio.NewReaderSize(stdout, 64*1024)\n\tlineCount := 0\n\tstartTime := time.Now()\n\n\tfor {\n\t\tline, skipped, err := shared.ReadJSONLine(reader)\n\t\tif err == io.EOF {\n\t\t\tif ctx.Err() != nil {\n\t\t\t\tp.closeTextMessage()\n\t\t\t\tp.closeThinkMessage()\n\t\t\t\tp.closeOrphanedTools()\n\t\t\t\treturn ctx.Err()\n\t\t\t}\n\t\t\tbreak\n\t\t}\n\t\tif err != nil {\n\t\t\tif ctx.Err() != nil {\n\t\t\t\tp.closeTextMessage()\n\t\t\t\tp.closeThinkMessage()\n\t\t\t\tp.closeOrphanedTools()\n\t\t\t\treturn ctx.Err()\n\t\t\t}\n\t\t\treturn err\n\t\t}\n\t\tif skipped || len(line) == 0 {\n\t\t\tcontinue\n\t\t}\n\t\tlineCount++\n\n\t\tvar msg jsonRPCMessage\n\t\tif err := json.Unmarshal(line, &msg); err != nil {\n\t\t\tlog.Trace(\"[dsh-parse] JSON unmarshal error: %v (len=%d)\", err, len(line))\n\t\t\tcontinue\n\t\t}\n\n\t\tstopped := p.dispatch(&msg)\n\t\tif stopped || p.completed {\n\t\t\tlog.Trace(\"[dsh-parse] done: lines=%d elapsed=%v completed=%v stopped=%v\", lineCount, time.Since(startTime).Round(time.Second), p.completed, stopped)\n\t\t\treturn nil\n\t\t}\n\t}\n\n\t// Ensure any active message groups are closed before returning.\n\tp.closeTextMessage()\n\tp.closeThinkMessage()\n\tp.closeOrphanedTools()\n\n\tlog.Trace(\"[dsh-parse] stream ended: lines=%d elapsed=%v completed=%v\", lineCount, time.Since(startTime).Round(time.Second), p.completed)\n\treturn nil\n}\n\nfunc (p *streamParser) dispatch(msg *jsonRPCMessage) (stopped bool) {\n\tif msg.isResponse() {\n\t\treturn p.handleResponse(msg)\n\t}\n\tif !msg.isNotification() {\n\t\treturn false\n\t}\n\tswitch msg.Method {\n\tcase \"session.event\":\n\t\treturn p.handleSessionEvent(msg.Params)\n\tcase \"session.status\":\n\t\treturn p.handleSessionStatus(msg.Params)\n\tcase \"session.completed\":\n\t\treturn p.handleSessionCompleted(msg.Params)\n\tcase \"session.waiting\":\n\t\treturn p.handleSessionWaiting(msg.Params)\n\t}\n\treturn false\n}\n\nfunc (p *streamParser) handleResponse(msg *jsonRPCMessage) (stopped bool) {\n\tif msg.Error != nil {\n\t\terrText := msg.Error.Message\n\t\tif p.handler != nil {\n\t\t\tp.handler(message.ChunkError, []byte(errText))\n\t\t}\n\t\treturn true\n\t}\n\t// Success responses are acknowledgments only — the plugin returns\n\t// session/prompt before the agent loop streams events.  Completion\n\t// is signaled by session.status \"idle\" or stdout EOF.\n\treturn false\n}\n\nfunc (p *streamParser) handleSessionStatus(raw json.RawMessage) (stopped bool) {\n\tvar params sessionStatusParams\n\tif err := json.Unmarshal(raw, &params); err != nil {\n\t\treturn false\n\t}\n\t// session.status:idle no longer drives completion — the Node side sends\n\t// session.completed after all descendants (subagents, team members, goal\n\t// rounds) have settled.  Keeping idle as a pure status notification\n\t// preserves event ordering for consumers that only observe status.\n\treturn false\n}\n\n// handleSessionCompleted processes the session.completed notification sent by\n// the Node side after the root agent and all descendant subagents are quiescent.\nfunc (p *streamParser) handleSessionCompleted(raw json.RawMessage) (stopped bool) {\n\tvar params sessionStatusParams\n\tif err := json.Unmarshal(raw, &params); err != nil {\n\t\treturn false\n\t}\n\tif p.promptedSessionID != \"\" && params.SessionID != p.promptedSessionID {\n\t\treturn false\n\t}\n\tp.closeTextMessage()\n\tp.closeThinkMessage()\n\tp.closeOrphanedTools()\n\tp.closeActiveLoading()\n\tp.completed = true\n\treturn false\n}\n\n// handleSessionWaiting processes the session.waiting notification emitted while\n// the root agent is idle but descendant subagents are still running.\nfunc (p *streamParser) handleSessionWaiting(raw json.RawMessage) (stopped bool) {\n\tp.emitLoading(i18n.T(p.locale, \"dsh.subagent.waiting\"))\n\treturn false\n}\n\nfunc (p *streamParser) handleSessionEvent(raw json.RawMessage) (stopped bool) {\n\tvar params sessionEventParams\n\tif err := json.Unmarshal(raw, &params); err != nil {\n\t\treturn false\n\t}\n\t// Allow events from child sessions (subagents, team members) to flow\n\t// through so their tool calls, text deltas, and lifecycle events are\n\t// visible to the Go consumer.  Only completion-critical logic (like\n\t// session.completed) is scoped to the prompted root session.\n\tevent := params.Event\n\n\tswitch event.Type {\n\tcase \"assistant/chunk\":\n\t\treturn p.handleAssistantChunk(event.Data)\n\tcase \"tool/call\":\n\t\treturn p.handleToolCall(event.Data)\n\tcase \"tool/result\":\n\t\treturn p.handleToolResult(event.Data)\n\tcase \"turn/end\":\n\t\treturn p.handleTurnEnd(event.Data)\n\n\t// compaction\n\tcase \"compaction/start\":\n\t\treturn p.handleCompactionStart(event.Data)\n\tcase \"compaction/end\":\n\t\treturn p.handleCompactionEnd(event.Data)\n\n\t// llm retry\n\tcase \"llm/retry\":\n\t\treturn p.handleLLMRetry(event.Data)\n\tcase \"llm/retry-started\":\n\t\treturn p.handleLLMRetryStarted(event.Data)\n\n\t// plan mode\n\tcase \"plan/mode\":\n\t\treturn p.handlePlanMode(event.Data)\n\n\t// subagent / workflow\n\tcase \"subagent/descriptor\":\n\t\treturn p.handleSubagentDescriptor(event.Data)\n\tcase \"tool-workflow/run-start\":\n\t\treturn p.handleWorkflowRunStart(event.Data)\n\tcase \"tool-workflow/run-end\":\n\t\treturn p.handleWorkflowRunEnd(event.Data)\n\tcase \"tool-workflow/agent-start\":\n\t\treturn p.handleWorkflowAgentStart(event.Data)\n\tcase \"tool-workflow/agent-end\":\n\t\treturn p.handleWorkflowAgentEnd(event.Data)\n\n\t// lifecycle metadata\n\tcase \"turn/start\":\n\t\treturn p.handleTurnStart(event.Data)\n\tcase \"step/start\":\n\t\treturn p.handleStepStart(event.Data)\n\tcase \"step/end\":\n\t\treturn p.handleStepEnd(event.Data)\n\tcase \"approval/asked\":\n\t\treturn p.handleApprovalAsked(event.Data)\n\tcase \"approval/decided\":\n\t\treturn p.handleApprovalDecided(event.Data)\n\t}\n\treturn false\n}\n\n// --- assistant/chunk handlers ---\n\ntype chunkData struct {\n\tTurn  int             `json:\"turn\"`\n\tStep  int             `json:\"step\"`\n\tChunk json.RawMessage `json:\"chunk\"`\n}\n\ntype chunkInner struct {\n\tType      string          `json:\"type\"`\n\tIndex     int             `json:\"index\"`\n\tText      string          `json:\"text\"`\n\tBlockType string          `json:\"blockType\"`\n\tBlock     json.RawMessage `json:\"block\"`\n\tID        string          `json:\"id\"`\n\tName      string          `json:\"name\"`\n\tArgsDelta string          `json:\"argumentsDelta\"`\n\tUsage     json.RawMessage `json:\"usage\"`\n\tReason    json.RawMessage `json:\"reason\"`\n}\n\nfunc (p *streamParser) handleAssistantChunk(data json.RawMessage) (stopped bool) {\n\tvar cd chunkData\n\tif err := json.Unmarshal(data, &cd); err != nil {\n\t\treturn false\n\t}\n\tvar chunk chunkInner\n\tif err := json.Unmarshal(cd.Chunk, &chunk); err != nil {\n\t\treturn false\n\t}\n\n\tswitch chunk.Type {\n\tcase \"text-delta\":\n\t\treturn p.onTextDelta(chunk.Text)\n\tcase \"reasoning-delta\":\n\t\treturn p.onReasoningDelta(chunk.Text)\n\tcase \"block-start\":\n\t\treturn p.onBlockStart(chunk)\n\tcase \"block-end\":\n\t\treturn p.onBlockEnd(chunk)\n\tcase \"tool-call-delta\":\n\t\treturn p.onToolCallDelta(chunk)\n\tcase \"usage\":\n\t\treturn p.onUsage(chunk.Usage)\n\tcase \"finish\":\n\t\treturn p.onFinish(chunk.Reason)\n\t}\n\treturn false\n}\n\nfunc (p *streamParser) onTextDelta(text string) (stopped bool) {\n\tif text == \"\" {\n\t\treturn false\n\t}\n\tp.closeActiveLoading()\n\tp.contentStarted = true\n\tp.closeThinkMessage()\n\tif !p.textActive {\n\t\tif p.beginMessage(\"text\") {\n\t\t\treturn true\n\t\t}\n\t\tp.textActive = true\n\t}\n\ttext = strings.ReplaceAll(text, \"\\r\\n\", \"\\n\")\n\ttext = strings.ReplaceAll(text, \"\\r\", \"\\n\")\n\treturn p.handler != nil && p.handler(message.ChunkText, []byte(text)) != 0\n}\n\nfunc (p *streamParser) onReasoningDelta(text string) (stopped bool) {\n\tif text == \"\" {\n\t\treturn false\n\t}\n\tp.closeActiveLoading()\n\tp.contentStarted = true\n\tp.closeTextMessage()\n\tif !p.thinkActive {\n\t\tif p.beginMessage(\"thinking\") {\n\t\t\treturn true\n\t\t}\n\t\tp.thinkActive = true\n\t}\n\treturn p.handler != nil && p.handler(message.ChunkThinking, []byte(text)) != 0\n}\n\nfunc (p *streamParser) onBlockStart(chunk chunkInner) (stopped bool) {\n\tswitch chunk.BlockType {\n\tcase \"tool-call\":\n\t\tp.closeActiveLoading()\n\t\tp.contentStarted = true\n\t\tp.closeTextMessage()\n\t\tp.closeThinkMessage()\n\t\ttoolID := chunk.ID\n\t\tif toolID == \"\" {\n\t\t\ttoolID = fmt.Sprintf(\"dsh-tool_%d_%d\", p.toolIndex, time.Now().UnixNano())\n\t\t}\n\t\tp.toolIndex++\n\t\tp.activeToolID = toolID\n\t\tif chunk.Name != \"\" {\n\t\t\tp.toolNames[toolID] = chunk.Name\n\t\t}\n\t\tmsgID := p.emitMessageStart(\"execute\")\n\t\tp.toolMsgIDs[toolID] = msgID\n\t\texecProps := map[string]any{\n\t\t\t\"tool\":    chunk.Name,\n\t\t\t\"tool_id\": toolID,\n\t\t\t\"status\":  \"running\",\n\t\t\t\"runner\":  \"dsh\",\n\t\t}\n\t\tinjectDSHSemanticType(execProps, chunk.Name)\n\t\tif p.emitExecute(execProps) {\n\t\t\tp.endMessage()\n\t\t\treturn true\n\t\t}\n\t\tp.endMessage()\n\tcase \"text\":\n\t\tp.closeActiveLoading()\n\t\tp.contentStarted = true\n\t\tp.closeThinkMessage()\n\t\tif !p.textActive {\n\t\t\tif p.beginMessage(\"text\") {\n\t\t\t\treturn true\n\t\t\t}\n\t\t\tp.textActive = true\n\t\t}\n\tcase \"reasoning\":\n\t\tp.closeActiveLoading()\n\t\tp.contentStarted = true\n\t\tp.closeTextMessage()\n\t\tif !p.thinkActive {\n\t\t\tif p.beginMessage(\"thinking\") {\n\t\t\t\treturn true\n\t\t\t}\n\t\t\tp.thinkActive = true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc (p *streamParser) onBlockEnd(chunk chunkInner) (stopped bool) {\n\tif p.activeToolID != \"\" {\n\t\ttoolID := p.activeToolID\n\t\toldSummary := p.toolSummaries[toolID]\n\t\tif input := p.toolInputs[toolID]; input != \"\" {\n\t\t\tname := p.toolNames[toolID]\n\t\t\tif summary := extractToolSummary(name, input); summary != \"\" {\n\t\t\t\tp.toolSummaries[toolID] = summary\n\t\t\t}\n\t\t}\n\t\tp.activeToolID = \"\"\n\n\t\t// Only emit update if summary actually changed (avoid duplicate with\n\t\t// delta-phase update), or if name became available but no summary was\n\t\t// sent yet.\n\t\tname := p.toolNames[toolID]\n\t\tnewSummary := p.toolSummaries[toolID]\n\t\tsummaryChanged := newSummary != oldSummary\n\t\tif summaryChanged || (name != \"\" && oldSummary == \"\") {\n\t\t\tif p.emitToolUpdate(toolID) {\n\t\t\t\treturn true\n\t\t\t}\n\t\t}\n\t\treturn false\n\t}\n\tif p.textActive {\n\t\tp.endMessage()\n\t\tp.textActive = false\n\t}\n\tif p.thinkActive {\n\t\tp.endMessage()\n\t\tp.thinkActive = false\n\t}\n\treturn false\n}\n\nfunc (p *streamParser) onToolCallDelta(chunk chunkInner) (stopped bool) {\n\tif p.activeToolID == \"\" {\n\t\treturn false\n\t}\n\tif chunk.ID != \"\" && chunk.ID != p.activeToolID {\n\t\tif msgID, ok := p.toolMsgIDs[p.activeToolID]; ok {\n\t\t\tp.toolMsgIDs[chunk.ID] = msgID\n\t\t}\n\t}\n\tnameJustSet := false\n\tif chunk.Name != \"\" && p.toolNames[p.activeToolID] == \"\" {\n\t\tp.toolNames[p.activeToolID] = chunk.Name\n\t\tnameJustSet = true\n\t}\n\tsummaryEmitted := false\n\tif chunk.ArgsDelta != \"\" {\n\t\texisting := p.toolInputs[p.activeToolID]\n\t\tp.toolInputs[p.activeToolID] = existing + chunk.ArgsDelta\n\n\t\ttoolName := p.toolNames[p.activeToolID]\n\t\tif s := extractToolSummaryPartial(toolName, p.toolInputs[p.activeToolID]); s != \"\" {\n\t\t\tif s != p.toolSummaries[p.activeToolID] {\n\t\t\t\tp.toolSummaries[p.activeToolID] = s\n\t\t\t\tif p.emitToolUpdate(p.activeToolID) {\n\t\t\t\t\treturn true\n\t\t\t\t}\n\t\t\t\tsummaryEmitted = true\n\t\t\t}\n\t\t}\n\t}\n\n\t// Emit update as soon as tool name arrives (first delta carries it).\n\t// Skip if a summary update already carried the name in this same delta.\n\tif nameJustSet && !summaryEmitted {\n\t\ttoolID := p.activeToolID\n\t\tname := p.toolNames[toolID]\n\t\tif msgID, ok := p.toolMsgIDs[toolID]; ok {\n\t\t\tp.beginMessageWithID(msgID, \"execute\")\n\t\t} else {\n\t\t\tp.emitMessageStart(\"execute\")\n\t\t}\n\t\texecProps := map[string]any{\n\t\t\t\"tool\":    name,\n\t\t\t\"tool_id\": toolID,\n\t\t\t\"status\":  \"running\",\n\t\t\t\"runner\":  \"dsh\",\n\t\t}\n\t\tinjectDSHSemanticType(execProps, name)\n\t\tif p.emitExecute(execProps) {\n\t\t\tp.endMessage()\n\t\t\treturn true\n\t\t}\n\t\tp.endMessage()\n\t}\n\treturn false\n}\n\nfunc (p *streamParser) onUsage(raw json.RawMessage) (stopped bool) {\n\tif p.handler == nil || len(raw) == 0 {\n\t\treturn false\n\t}\n\tdata, _ := json.Marshal(map[string]any{\"usage\": json.RawMessage(raw)})\n\tp.handler(message.ChunkMetadata, data)\n\treturn false\n}\n\nfunc (p *streamParser) onFinish(raw json.RawMessage) (stopped bool) {\n\tif p.handler == nil || len(raw) == 0 {\n\t\treturn false\n\t}\n\tvar reason map[string]any\n\tjson.Unmarshal(raw, &reason)\n\tdata, _ := json.Marshal(map[string]any{\"finish_reason\": reason})\n\tp.handler(message.ChunkMetadata, data)\n\treturn false\n}\n\n// --- tool/call and tool/result handlers ---\n\ntype toolCallData struct {\n\tTurn      int    `json:\"turn\"`\n\tStep      int    `json:\"step\"`\n\tCallID    string `json:\"callId\"`\n\tName      string `json:\"name\"`\n\tArguments string `json:\"arguments\"`\n}\n\ntype toolResultData struct {\n\tTurn    int             `json:\"turn\"`\n\tStep    int             `json:\"step\"`\n\tMessage json.RawMessage `json:\"message\"`\n\tMeta    json.RawMessage `json:\"meta,omitempty\"`\n}\n\ntype toolResultMessage struct {\n\tSource  map[string]any `json:\"source\"`\n\tContent []any          `json:\"content\"`\n}\n\nfunc (p *streamParser) handleToolCall(data json.RawMessage) (stopped bool) {\n\tvar tc toolCallData\n\tif err := json.Unmarshal(data, &tc); err != nil {\n\t\treturn false\n\t}\n\tp.closeActiveLoading()\n\tp.contentStarted = true\n\tp.closeTextMessage()\n\tp.closeThinkMessage()\n\n\ttoolID := tc.CallID\n\tp.toolNames[toolID] = tc.Name\n\tif tc.Arguments != \"\" {\n\t\tp.toolInputs[toolID] = tc.Arguments\n\t}\n\n\tsummary := p.toolSummaries[toolID]\n\tif tc.Arguments != \"\" {\n\t\tif s := extractToolSummary(tc.Name, tc.Arguments); s != \"\" {\n\t\t\tsummary = s\n\t\t\tp.toolSummaries[toolID] = summary\n\t\t}\n\t}\n\n\tif msgID, ok := p.toolMsgIDs[toolID]; ok {\n\t\tp.beginMessageWithID(msgID, \"execute\")\n\t} else {\n\t\tmsgID := p.emitMessageStart(\"execute\")\n\t\tp.toolMsgIDs[toolID] = msgID\n\t}\n\n\tinput := p.toolInputs[toolID]\n\tvar inputJSON json.RawMessage\n\tif input != \"\" {\n\t\tinputJSON = json.RawMessage(input)\n\t}\n\n\texecProps := map[string]any{\n\t\t\"tool\":    tc.Name,\n\t\t\"tool_id\": toolID,\n\t\t\"input\":   inputJSON,\n\t\t\"summary\": summary,\n\t\t\"status\":  \"running\",\n\t\t\"runner\":  \"dsh\",\n\t}\n\tinjectDSHSemanticType(execProps, tc.Name)\n\tif p.emitExecute(execProps) {\n\t\tp.endMessage()\n\t\treturn true\n\t}\n\tp.endMessage()\n\treturn false\n}\n\nfunc (p *streamParser) handleToolResult(data json.RawMessage) (stopped bool) {\n\tvar tr toolResultData\n\tif err := json.Unmarshal(data, &tr); err != nil {\n\t\treturn false\n\t}\n\n\t// Extract callId and content from the tool result message\n\tvar trMsg toolResultMessage\n\tjson.Unmarshal(tr.Message, &trMsg)\n\n\tcallID := \"\"\n\tif source := trMsg.Source; source != nil {\n\t\tif id, ok := source[\"callId\"].(string); ok {\n\t\t\tcallID = id\n\t\t}\n\t}\n\n\t// Extract output text from content\n\toutput := extractToolOutput(trMsg.Content)\n\tisError := false\n\tfor _, item := range trMsg.Content {\n\t\tif m, ok := item.(map[string]any); ok {\n\t\t\tif e, ok := m[\"isError\"].(bool); ok && e {\n\t\t\t\tisError = true\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\n\tstatus := \"completed\"\n\tif isError {\n\t\tstatus = \"error\"\n\t}\n\n\tif msgID, ok := p.toolMsgIDs[callID]; ok {\n\t\tp.beginMessageWithID(msgID, \"execute\")\n\t} else {\n\t\tp.emitMessageStart(\"execute\")\n\t}\n\n\texecProps := map[string]any{\n\t\t\"tool_id\":  callID,\n\t\t\"output\":   output,\n\t\t\"status\":   status,\n\t\t\"is_error\": isError,\n\t}\n\tif name, ok := p.toolNames[callID]; ok {\n\t\texecProps[\"tool\"] = name\n\t}\n\tif input, ok := p.toolInputs[callID]; ok && input != \"\" {\n\t\texecProps[\"input\"] = json.RawMessage(input)\n\t}\n\tif summary, ok := p.toolSummaries[callID]; ok {\n\t\texecProps[\"summary\"] = summary\n\t}\n\tif len(tr.Meta) > 0 {\n\t\tif patches := computeFilePatches(tr.Meta); len(patches) > 0 {\n\t\t\texecProps[\"file_patches\"] = patches\n\t\t}\n\t}\n\tinjectDSHSemanticType(execProps, p.toolNames[callID])\n\tif p.emitExecute(execProps) {\n\t\tp.toolFinished[callID] = true\n\t\tp.endMessage()\n\t\treturn true\n\t}\n\tp.toolFinished[callID] = true\n\tp.endMessage()\n\treturn false\n}\n\n// --- turn/end ---\n\ntype turnEndData struct {\n\tTurn   int            `json:\"turn\"`\n\tReason map[string]any `json:\"reason\"`\n}\n\nfunc (p *streamParser) handleTurnEnd(data json.RawMessage) (stopped bool) {\n\tvar te turnEndData\n\tif err := json.Unmarshal(data, &te); err != nil {\n\t\treturn false\n\t}\n\tp.closeTextMessage()\n\tp.closeThinkMessage()\n\n\tif p.handler != nil {\n\t\tsummary, _ := json.Marshal(map[string]any{\n\t\t\t\"result_summary\": map[string]any{\n\t\t\t\t\"turn\":   te.Turn,\n\t\t\t\t\"reason\": te.Reason,\n\t\t\t},\n\t\t})\n\t\tp.handler(message.ChunkMetadata, summary)\n\t}\n\n\t// Surface DSH errors with full detail from the reason payload\n\tif kind, ok := te.Reason[\"kind\"].(string); ok && kind != \"completed\" && kind != \"stop\" {\n\t\terrMsg := formatTurnError(te.Reason)\n\t\tlog.Warn(\"[dsh-parse] turn ended with error: kind=%s msg=%s\", kind, errMsg)\n\t\tif p.handler != nil {\n\t\t\tp.handler(message.ChunkError, []byte(errMsg))\n\t\t}\n\t}\n\n\treturn false\n}\n\n// --- message lifecycle helpers ---\n\nfunc (p *streamParser) beginMessage(msgType string) (stopped bool) {\n\tstartData := message.EventMessageStartData{\n\t\tMessageID: fmt.Sprintf(\"dsh-%s-%s\", msgType, message.GenerateNanoID()),\n\t\tType:      msgType,\n\t\tTimestamp: time.Now().UnixMilli(),\n\t}\n\tsd, _ := json.Marshal(startData)\n\treturn p.handler != nil && p.handler(message.ChunkMessageStart, sd) != 0\n}\n\nfunc (p *streamParser) emitMessageStart(msgType string) string {\n\tid := fmt.Sprintf(\"dsh-%s-%s\", msgType, message.GenerateNanoID())\n\tstartData := message.EventMessageStartData{\n\t\tMessageID: id,\n\t\tType:      msgType,\n\t\tTimestamp: time.Now().UnixMilli(),\n\t}\n\tsd, _ := json.Marshal(startData)\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkMessageStart, sd)\n\t}\n\treturn id\n}\n\nfunc (p *streamParser) beginMessageWithID(id, msgType string) {\n\tstartData := message.EventMessageStartData{\n\t\tMessageID: id,\n\t\tType:      msgType,\n\t\tTimestamp: time.Now().UnixMilli(),\n\t}\n\tsd, _ := json.Marshal(startData)\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkMessageStart, sd)\n\t}\n}\n\nfunc (p *streamParser) endMessage() {\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkMessageEnd, nil)\n\t}\n}\n\nfunc (p *streamParser) closeTextMessage() {\n\tif p.textActive {\n\t\tp.endMessage()\n\t\tp.textActive = false\n\t}\n}\n\nfunc (p *streamParser) closeThinkMessage() {\n\tif p.thinkActive {\n\t\tp.endMessage()\n\t\tp.thinkActive = false\n\t}\n}\n\nfunc (p *streamParser) closeOrphanedTools() {\n\t// Collect msgIDs of already-finished tools to handle aliases\n\t// (synthetic block-start ID and real callId both map to same msgID).\n\tfinishedMsgIDs := make(map[string]bool)\n\tfor toolID := range p.toolFinished {\n\t\tif msgID, ok := p.toolMsgIDs[toolID]; ok {\n\t\t\tfinishedMsgIDs[msgID] = true\n\t\t}\n\t}\n\n\tfor toolID, msgID := range p.toolMsgIDs {\n\t\tif p.toolFinished[toolID] || finishedMsgIDs[msgID] {\n\t\t\tcontinue\n\t\t}\n\t\tp.beginMessageWithID(msgID, \"execute\")\n\t\texecProps := map[string]any{\n\t\t\t\"tool_id\":  toolID,\n\t\t\t\"status\":   \"error\",\n\t\t\t\"is_error\": true,\n\t\t\t\"output\":   \"session ended before tool completed\",\n\t\t}\n\t\tif name, ok := p.toolNames[toolID]; ok {\n\t\t\texecProps[\"tool\"] = name\n\t\t}\n\t\tif summary, ok := p.toolSummaries[toolID]; ok {\n\t\t\texecProps[\"summary\"] = summary\n\t\t}\n\t\tinjectDSHSemanticType(execProps, p.toolNames[toolID])\n\t\tp.emitExecute(execProps)\n\t\tp.endMessage()\n\t\tfinishedMsgIDs[msgID] = true\n\t}\n}\n\nfunc (p *streamParser) emitToolUpdate(toolID string) (stopped bool) {\n\tname := p.toolNames[toolID]\n\tsummary := p.toolSummaries[toolID]\n\tif msgID, ok := p.toolMsgIDs[toolID]; ok {\n\t\tp.beginMessageWithID(msgID, \"execute\")\n\t} else {\n\t\tp.emitMessageStart(\"execute\")\n\t}\n\texecProps := map[string]any{\n\t\t\"tool\":    name,\n\t\t\"tool_id\": toolID,\n\t\t\"status\":  \"running\",\n\t\t\"runner\":  \"dsh\",\n\t}\n\tif summary != \"\" {\n\t\texecProps[\"summary\"] = summary\n\t}\n\tinjectDSHSemanticType(execProps, name)\n\tif p.emitExecute(execProps) {\n\t\tp.endMessage()\n\t\treturn true\n\t}\n\tp.endMessage()\n\treturn false\n}\n\nfunc (p *streamParser) emitExecute(props map[string]any) (stopped bool) {\n\tdata, err := json.Marshal(props)\n\tif err != nil {\n\t\treturn false\n\t}\n\treturn p.handler != nil && p.handler(message.ChunkExecute, data) != 0\n}\n\n// --- helpers ---\n\nfunc extractToolOutput(content []any) any {\n\tif len(content) == 0 {\n\t\treturn nil\n\t}\n\tvar texts []string\n\tfor _, item := range content {\n\t\tif m, ok := item.(map[string]any); ok {\n\t\t\tif c, ok := m[\"content\"].([]any); ok {\n\t\t\t\tfor _, ci := range c {\n\t\t\t\t\tif cm, ok := ci.(map[string]any); ok {\n\t\t\t\t\t\tif text, ok := cm[\"text\"].(string); ok {\n\t\t\t\t\t\t\ttexts = append(texts, text)\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\tif len(texts) == 1 {\n\t\treturn texts[0]\n\t}\n\tif len(texts) > 1 {\n\t\treturn strings.Join(texts, \"\\n\")\n\t}\n\treturn content\n}\n\nfunc extractSummaryFromObj(toolName string, obj map[string]any) string {\n\tswitch strings.ToLower(toolName) {\n\tcase \"bash\":\n\t\tif desc, ok := obj[\"description\"].(string); ok && desc != \"\" {\n\t\t\treturn truncateStr(desc, 80)\n\t\t}\n\t\tif cmd, ok := obj[\"command\"].(string); ok {\n\t\t\treturn truncateStr(cmd, 80)\n\t\t}\n\tcase \"write\", \"read\", \"edit\", \"str_replace_editor\":\n\t\tif fp, ok := obj[\"file_path\"].(string); ok {\n\t\t\treturn fp\n\t\t}\n\t\tif fp, ok := obj[\"path\"].(string); ok {\n\t\t\treturn fp\n\t\t}\n\tcase \"skill\":\n\t\tif n, ok := obj[\"name\"].(string); ok {\n\t\t\treturn truncateStr(n, 80)\n\t\t}\n\t\tif d, ok := obj[\"description\"].(string); ok {\n\t\t\treturn truncateStr(d, 80)\n\t\t}\n\t}\n\n\tfor _, key := range []string{\"description\", \"command\", \"path\", \"file_path\", \"url\", \"query\", \"prompt\", \"task\", \"name\"} {\n\t\tif v, ok := obj[key].(string); ok {\n\t\t\treturn truncateStr(v, 80)\n\t\t}\n\t}\n\treturn \"\"\n}\n\nfunc extractToolSummary(toolName, inputJSON string) string {\n\tif inputJSON == \"\" {\n\t\treturn \"\"\n\t}\n\tvar obj map[string]any\n\tif err := json.Unmarshal([]byte(inputJSON), &obj); err != nil {\n\t\treturn \"\"\n\t}\n\treturn extractSummaryFromObj(toolName, obj)\n}\n\nfunc extractToolSummaryPartial(toolName, partialInput string) string {\n\tif partialInput == \"\" {\n\t\treturn \"\"\n\t}\n\tv, err := gouJSON.Parse(partialInput)\n\tif err == nil {\n\t\tif obj, ok := v.(map[string]any); ok {\n\t\t\treturn extractSummaryFromObj(toolName, obj)\n\t\t}\n\t}\n\treturn extractSummaryByRegex(toolName, partialInput)\n}\n\nvar summaryKeyRe = regexp.MustCompile(`\"(description|file_path|path|command|name|url|query|prompt|task)\"\\s*:\\s*\"([^\"]*)\"`)\n\nfunc extractSummaryByRegex(toolName string, input string) string {\n\tmatches := summaryKeyRe.FindAllStringSubmatch(input, -1)\n\tif len(matches) == 0 {\n\t\treturn \"\"\n\t}\n\tpreferred := preferredKeyForTool(toolName)\n\tfor _, m := range matches {\n\t\tif m[1] == preferred && m[2] != \"\" {\n\t\t\treturn truncateStr(m[2], 80)\n\t\t}\n\t}\n\tif matches[0][2] != \"\" {\n\t\treturn truncateStr(matches[0][2], 80)\n\t}\n\treturn \"\"\n}\n\nfunc preferredKeyForTool(toolName string) string {\n\tswitch strings.ToLower(toolName) {\n\tcase \"bash\":\n\t\treturn \"description\"\n\tcase \"write\", \"read\", \"edit\", \"str_replace_editor\":\n\t\treturn \"file_path\"\n\tcase \"skill\":\n\t\treturn \"name\"\n\tdefault:\n\t\treturn \"\"\n\t}\n}\n\nfunc truncateStr(s string, max int) string {\n\ts = strings.TrimSpace(s)\n\ts = strings.ReplaceAll(s, \"\\n\", \" \")\n\tif len(s) > max {\n\t\treturn s[:max] + \"...\"\n\t}\n\treturn s\n}\n\nfunc formatTurnError(reason map[string]any) string {\n\tkind, _ := reason[\"kind\"].(string)\n\tmsg, _ := reason[\"message\"].(string)\n\tif msg != \"\" {\n\t\treturn msg\n\t}\n\n\tif errStr, ok := reason[\"error\"].(string); ok && errStr != \"\" {\n\t\treturn errStr\n\t}\n\n\tif errMap, ok := reason[\"error\"].(map[string]any); ok {\n\t\tif errMsg, ok := errMap[\"message\"].(string); ok && errMsg != \"\" {\n\t\t\treturn errMsg\n\t\t}\n\t\tif errCode, ok := errMap[\"code\"].(string); ok && errCode != \"\" {\n\t\t\treturn errCode\n\t\t}\n\t}\n\n\tdetail, _ := json.Marshal(reason)\n\treturn fmt.Sprintf(\"DSH turn ended: %s (%s)\", kind, string(detail))\n}\n\nfunc injectDSHSemanticType(props map[string]any, toolName string) {\n\tswitch strings.ToLower(toolName) {\n\tcase \"subagent\":\n\t\tprops[\"semantic_type\"] = message.TypeAgent\n\tcase \"todo_write\", \"todo\":\n\t\tprops[\"semantic_type\"] = message.TypeTodo\n\tcase \"ask-user\":\n\t\tprops[\"semantic_type\"] = message.TypeQuestion\n\t}\n}\n\n// --- loading status helpers ---\n\nfunc (p *streamParser) emitLoading(text string) {\n\tvar msg *message.Message\n\n\tif !p.contentStarted && p.prepareLoadingMsgID != \"\" {\n\t\tmsg = &message.Message{\n\t\t\tMessageID:   p.prepareLoadingMsgID,\n\t\t\tDelta:       true,\n\t\t\tDeltaAction: message.DeltaReplace,\n\t\t\tType:        message.TypeLoading,\n\t\t\tProps:       map[string]any{\"message\": text},\n\t\t}\n\t} else if p.activeLoadingID != \"\" {\n\t\tmsg = &message.Message{\n\t\t\tMessageID:   p.activeLoadingID,\n\t\t\tDelta:       true,\n\t\t\tDeltaAction: message.DeltaReplace,\n\t\t\tType:        message.TypeLoading,\n\t\t\tProps:       map[string]any{\"message\": text},\n\t\t}\n\t} else {\n\t\tp.loadingSeq++\n\t\tp.activeLoadingID = fmt.Sprintf(\"dsh-loading-%d\", p.loadingSeq)\n\t\tmsg = &message.Message{\n\t\t\tMessageID: p.activeLoadingID,\n\t\t\tType:      message.TypeLoading,\n\t\t\tProps:     map[string]any{\"message\": text},\n\t\t}\n\t}\n\n\tdata, _ := json.Marshal(msg)\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkLoading, data)\n\t}\n}\n\nfunc (p *streamParser) closeActiveLoading() {\n\tif p.activeLoadingID == \"\" {\n\t\treturn\n\t}\n\tmsg := &message.Message{\n\t\tMessageID:   p.activeLoadingID,\n\t\tDelta:       true,\n\t\tDeltaAction: message.DeltaReplace,\n\t\tType:        message.TypeLoading,\n\t\tProps:       map[string]any{\"done\": true, \"message\": \"\"},\n\t}\n\tdata, _ := json.Marshal(msg)\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkLoading, data)\n\t}\n\tp.activeLoadingID = \"\"\n}\n\n// --- compaction handlers ---\n\nfunc (p *streamParser) handleCompactionStart(data json.RawMessage) (stopped bool) {\n\tp.emitLoading(i18n.T(p.locale, \"dsh.compaction.running\"))\n\treturn false\n}\n\nfunc (p *streamParser) handleCompactionEnd(data json.RawMessage) (stopped bool) {\n\tvar d struct {\n\t\tError string `json:\"error\"`\n\t}\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tif d.Error != \"\" {\n\t\tp.emitLoading(fmt.Sprintf(i18n.T(p.locale, \"dsh.compaction.error\"), d.Error))\n\t} else {\n\t\tp.emitLoading(i18n.T(p.locale, \"dsh.compaction.completed\"))\n\t}\n\treturn false\n}\n\n// --- llm retry handlers ---\n\nfunc (p *streamParser) handleLLMRetry(data json.RawMessage) (stopped bool) {\n\tvar d struct {\n\t\tMode       string  `json:\"mode\"`\n\t\tRetry      float64 `json:\"retry\"`\n\t\tMaxRetries float64 `json:\"maxRetries\"`\n\t\tDelayMs    float64 `json:\"delayMs\"`\n\t}\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tretry := int(d.Retry)\n\tdelaySec := int(d.DelayMs / 1000)\n\tvar msg string\n\tif d.Mode == \"always\" {\n\t\tmsg = fmt.Sprintf(i18n.T(p.locale, \"dsh.retry.waiting_always\"), retry, delaySec)\n\t} else {\n\t\tmsg = fmt.Sprintf(i18n.T(p.locale, \"dsh.retry.waiting\"), retry, int(d.MaxRetries), delaySec)\n\t}\n\tp.emitLoading(msg)\n\treturn false\n}\n\nfunc (p *streamParser) handleLLMRetryStarted(data json.RawMessage) (stopped bool) {\n\treturn false\n}\n\n// --- plan/mode handler ---\n\nfunc (p *streamParser) handlePlanMode(data json.RawMessage) (stopped bool) {\n\tvar d struct {\n\t\tActive bool `json:\"active\"`\n\t}\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tif d.Active {\n\t\tp.emitLoading(i18n.T(p.locale, \"dsh.plan.enter\"))\n\t} else {\n\t\tp.emitLoading(i18n.T(p.locale, \"dsh.plan.exit\"))\n\t}\n\treturn false\n}\n\n// --- subagent/descriptor handler ---\n\nfunc (p *streamParser) handleSubagentDescriptor(data json.RawMessage) (stopped bool) {\n\tvar d map[string]any\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tmeta := map[string]any{}\n\tif mode, ok := d[\"mode\"]; ok {\n\t\tmeta[\"mode\"] = mode\n\t}\n\tif provider, ok := d[\"provider\"]; ok {\n\t\tmeta[\"provider\"] = provider\n\t}\n\tif label, ok := d[\"label\"]; ok {\n\t\tmeta[\"label\"] = label\n\t}\n\tpayload, _ := json.Marshal(map[string]any{\"subagent\": meta})\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkMetadata, payload)\n\t}\n\treturn false\n}\n\n// --- tool-workflow handlers ---\n\nfunc (p *streamParser) handleWorkflowRunStart(data json.RawMessage) (stopped bool) {\n\tvar d struct {\n\t\tName string `json:\"name\"`\n\t}\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tp.emitLoading(d.Name)\n\treturn false\n}\n\nfunc (p *streamParser) handleWorkflowRunEnd(data json.RawMessage) (stopped bool) {\n\treturn false\n}\n\nfunc (p *streamParser) handleWorkflowAgentStart(data json.RawMessage) (stopped bool) {\n\tvar d struct {\n\t\tLabel string `json:\"label\"`\n\t}\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tp.emitLoading(d.Label)\n\treturn false\n}\n\nfunc (p *streamParser) handleWorkflowAgentEnd(data json.RawMessage) (stopped bool) {\n\treturn false\n}\n\n// --- lifecycle metadata handlers ---\n\nfunc (p *streamParser) handleTurnStart(data json.RawMessage) (stopped bool) {\n\tp.emitLoading(i18n.T(p.locale, \"dsh.turn.processing\"))\n\treturn false\n}\n\nfunc (p *streamParser) handleStepStart(data json.RawMessage) (stopped bool) {\n\tp.emitLoading(i18n.T(p.locale, \"dsh.step.thinking\"))\n\treturn false\n}\n\nfunc (p *streamParser) handleStepEnd(data json.RawMessage) (stopped bool) {\n\tvar d struct {\n\t\tTurn int `json:\"turn\"`\n\t\tStep int `json:\"step\"`\n\t}\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tpayload, _ := json.Marshal(map[string]any{\"step_end\": map[string]any{\"turn\": d.Turn, \"step\": d.Step}})\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkMetadata, payload)\n\t}\n\treturn false\n}\n\nfunc (p *streamParser) handleApprovalAsked(data json.RawMessage) (stopped bool) {\n\tvar d map[string]any\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tpayload, _ := json.Marshal(map[string]any{\"approval_asked\": d})\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkMetadata, payload)\n\t}\n\treturn false\n}\n\nfunc (p *streamParser) handleApprovalDecided(data json.RawMessage) (stopped bool) {\n\tvar d map[string]any\n\tif err := json.Unmarshal(data, &d); err != nil {\n\t\treturn false\n\t}\n\tpayload, _ := json.Marshal(map[string]any{\"approval_decided\": d})\n\tif p.handler != nil {\n\t\tp.handler(message.ChunkMetadata, payload)\n\t}\n\treturn false\n}\n"
